// Budgeting helper (pseudo)
function budgetForTenant(ckne, baseConcurrency, baseCacheBudget) {
  const s = Math.max(0, Math.min(1, ckne));
  return {
    concurrency: Math.max(1, Math.round(baseConcurrency * (0.5 + 0.5 * s))),
    cacheBudget: Math.round(baseCacheBudget * (1 - s))
